def max_uptime(status, k):
    left = 0
    zeros = 0
    best = 0
    for right in range(len(status)):
        if status[right] == 0:
            zeros += 1
        while zeros > k:
            if status[left] == 0:
                zeros -= 1
            left += 1
        best = max(best, right - left + 1)
    return best
